Specification:
A waiter blocks on a condition variable until a predicate guarded by a mutex becomes true; a notifier makes it true and signals. The waiter must complete even if the signal arrives before it waits. On completion the program must print exactly one line `DONE ready=true` and then exit; it must terminate.


Current program:
```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    let pair = Arc::new((Mutex::new(false), Condvar::new()));

    let pair_w = Arc::clone(&pair);
    let waiter = thread::spawn(move || {
        let (mtx, cv) = &*pair_w;
        let guard = mtx.lock().unwrap();

        let guard = cv.wait(guard).unwrap();
        drop(guard);
    });

    let pair_n = Arc::clone(&pair);
    let notifier = thread::spawn(move || {
        let (mtx, cv) = &*pair_n;
        let mut ready = mtx.lock().unwrap();
        *ready = true;
        cv.notify_all();
        drop(ready);
    });

    waiter.join().unwrap();
    notifier.join().unwrap();
}

```

